function norm(value=''){return String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();}
function freezeExercise(ex){return Object.freeze({...ex,primary_muscles:Object.freeze([...(ex.primary_muscles||[])]),secondary_muscles:Object.freeze([...(ex.secondary_muscles||[])]),cues:Object.freeze([...(ex.cues||[])]),instructions_es:Object.freeze([...(ex.instructions_es||[])]),precautions:Object.freeze([...(ex.precautions||[])]),tags:Object.freeze([...(ex.tags||[])])});}
export function createExerciseCatalog(records=[]){
 const map=new Map();
 for(const raw of records){if(!raw?.id||!raw?.name_es) continue; if(map.has(raw.id)) throw new Error(`M26_EXERCISE_DUPLICATE:${raw.id}`); map.set(raw.id,freezeExercise(raw));}
 const list=Object.freeze([...map.values()]);
 const facets=Object.freeze({patterns:Object.freeze([...new Set(list.map(x=>x.pattern).filter(Boolean))].sort()),equipment:Object.freeze([...new Set(list.map(x=>x.equipment).filter(Boolean))].sort()),difficulty:Object.freeze([...new Set(list.map(x=>x.difficulty).filter(Boolean))].sort()),intent:Object.freeze([...new Set(list.map(x=>x.intent).filter(Boolean))].sort())});
 function search(query='',filters={}){const q=norm(query);return list.filter(ex=>{const hay=norm([ex.name_es,ex.pattern,ex.intent,ex.equipment,ex.difficulty,...ex.primary_muscles,...ex.secondary_muscles,...ex.tags].join(' '));if(q&&!hay.includes(q))return false;for(const [key,value] of Object.entries(filters)){if(value==null||value===''||(Array.isArray(value)&&!value.length))continue;const expected=Array.isArray(value)?value:[value];if(!expected.some(v=>norm(ex[key]).includes(norm(v))))return false;}return true;});}
 return Object.freeze({count:list.length,list:()=>list,get:id=>map.get(id)||null,has:id=>map.has(id),search,facets});
}
export async function loadExerciseCatalog(source){let records;if(Array.isArray(source))records=source;else if(typeof source==='string'){const browser=typeof window!=='undefined'&&typeof fetch==='function';const remote=/^https?:\/\//i.test(source);if(browser||remote){const r=await fetch(source);if(!r.ok)throw new Error('M26_EXERCISE_CATALOG_FETCH_FAILED');records=await r.json();}else{const {readFile}=await import('node:fs/promises');records=JSON.parse(await readFile(source,'utf8'));}}else throw new Error('M26_EXERCISE_CATALOG_SOURCE_REQUIRED');const catalog=createExerciseCatalog(records);if(catalog.count<367)throw new Error(`M26_EXERCISE_CATALOG_INCOMPLETE:${catalog.count}`);return catalog;}
